example_solution:
package nucleotidecount

import (
	"errors"
	"strings"
)

// DNA is a list of nucleotides
type (
	DNA       string
	Histogram map[byte]int
)

const validNucleotides = "ACGT"

// Counts generates a histogram of valid nucleotides in given DNA.
// Returns error if DNA contains invalid nucleotide.
func (dna DNA) Counts() (Histogram, error) {
	var total int
	result := make(Histogram)

	for i := range validNucleotides {
		nucleotide := validNucleotides[i]
		result[nucleotide] = strings.Count(string(dna), string(nucleotide))
		total += result[nucleotide]
	}
	if total != len(dna) {
		return nil, errors.New("dna: contains invalid nucleotide")
	}
	return result, nil
}

test_code:
package nucleotidecount

import (
	"reflect"
	"testing"
)

func TestCounts(t *testing.T) {
	for _, tc := range testCases {
		t.Run(tc.description, func(t *testing.T) {
			dna := DNA(tc.strand)
			actual, err := dna.Counts()
			switch {
			case tc.errorExpected:
				if err == nil {
					t.Fatalf("DNA.Counts(%q) expected error, got: %#v", tc.strand, actual)
				}
			case err != nil:
				t.Fatalf("DNA.Counts(%q) returned error: %v, want: %#v", tc.strand, err, tc.expected)
			case !reflect.DeepEqual(actual, tc.expected):
				t.Fatalf("DNA.Counts(%q)\ngot: %#v\nwant: %#v", tc.strand, actual, tc.expected)
			}
		})
	}
}

func BenchmarkCounts(b *testing.B) {
	for range b.N {
		for _, tc := range testCases {
			dna := DNA(tc.strand)
			dna.Counts()
		}
	}
}
